// Zweck: prüft einen Auftrag aus dem Dashboard, bevor K1 startet. Gleiche Grenzen wie im Formular von K1.
const cfg = $('Konfiguration [Edit Fields]').first().json;
// Warum Typprüfung: ein Body, der kein Objekt ist, soll eine 400 ergeben, keinen Absturz.
const rawBody = $input.first().json.body;
const b = (rawBody && typeof rawBody === 'object' && !Array.isArray(rawBody)) ? rawBody : {};
const s = v => (typeof v === 'string' ? v.trim() : '');
const types = ['Thema', 'Artikel-Link', 'YouTube-Link', 'Eigener Text'];
const job = {
  customer_code: s(b.customer_code).toLowerCase(),
  source_type: s(b.source_type),
  topic: s(b.topic),
  source: s(b.source),
  note: s(b.note),
};
const errors = [];
// Warum hier und nicht erst in K1: ein ungültiger Auftrag kostet so keinen Modellaufruf.
if (!/^[a-z0-9-]{2,40}$/.test(job.customer_code)) errors.push('Kunde fehlt oder ist ungültig.');
if (!types.includes(job.source_type)) errors.push('Quellenart ist unbekannt.');
if (job.topic.length < 3 || job.topic.length > 200) errors.push('Das Thema braucht 3 bis 200 Zeichen.');
if (job.source_type !== 'Thema' && !job.source) errors.push('Für diese Quellenart fehlt die Quelle.');
if ((job.source_type === 'Artikel-Link' || job.source_type === 'YouTube-Link') && job.source && !/^https:\/\/\S+$/.test(job.source)) errors.push('Die Quelle muss eine vollständige Adresse mit https:// sein.');
if (job.source.length > 20000) errors.push('Die Quelle ist länger als 20.000 Zeichen.');
if (job.note.length > 1000) errors.push('Der Hinweis ist länger als 1.000 Zeichen.');

const ok = errors.length === 0;
// Warum ein Schalter: vor dem Aktivieren (Basic Auth, Aufrufrecht in K1) soll das Dashboard keinen echten Lauf auslösen.
const dispatch = cfg.dispatch_enabled === true;
let status_code = 200;
let response;
if (!ok) {
  status_code = 400;
  response = { ok: false, started: false, message: 'Auftrag nicht gestartet.', errors };
} else if (!dispatch) {
  response = { ok: true, started: false, message: `Probebetrieb: Der Auftrag für ${job.customer_code} ist gültig, wurde aber nicht an K1 übergeben. Zum Starten in der Konfiguration dispatch_enabled auf true setzen.` };
} else {
  status_code = 202;
  response = { ok: true, started: true, message: `Auftrag an K1 übergeben (${job.source_type}: ${job.topic}). Die Vorschau kommt zur Freigabe in Telegram.` };
}
return [{ json: { ...job, start_k1: ok && dispatch, status_code, response } }];

// Zweck: baut die Dashboard-Seite aus Vorlage, Läufen, Tageswerten und Kunden. Alle Abfragen liefen serverseitig, im HTML steht kein Schlüssel.
const cfg = $('Konfiguration [Edit Fields]').first().json;
// Warum Vorlage aus Supabase: die Seite (rund 50 KB) liegt als nur lesende Funktion k1_dashboard_template() in der Datenbank und wird dort versioniert.
const raw = $('Vorlage laden [HTTP Request]').first().json.data;
let TEMPLATE = typeof raw === 'string' ? raw : '';
try { const p = JSON.parse(TEMPLATE); if (typeof p === 'string') TEMPLATE = p; } catch (e) { /* Antwort war schon reiner Text */ }
if (!TEMPLATE.includes('/*__DATA__*/null')) {
  throw new Error('Vorlage ohne Platzhalter erhalten (' + TEMPLATE.length + ' Zeichen), Seite nicht baubar.');
}
// Warum filtern: die Ladeknoten geben bei leerer Tabelle ein leeres Element weiter (alwaysOutputData), das darf nicht als Lauf zählen.
const runs = $('Läufe laden [HTTP Request]').all().map(i => i.json).filter(r => r && r.logged_at);
const dailyRaw = $('Tageswerte laden [HTTP Request]').all().map(i => i.json).filter(d => d && d.day);
const customers = $('Kunden laden [HTTP Request]').all().map(i => i.json).filter(c => c && c.kuerzel).map(c => ({
  code: c.kuerzel,
  name: c.name,
  active: c.aktiv === true,
  branding: {
    markenname: c.branding_pack?.markenname ?? null,
    farben: c.branding_pack?.farben ?? null,
    schriften: c.branding_pack?.schriften ?? null,
    // Warum Version: die Seite sendet sie beim Speichern als erwartete Version mit.
    version: Number(c.branding_pack?.version) || 0,
  },
}));

// Warum Lücken füllen: ein Tag ohne Lauf soll als leere Spalte sichtbar sein, sonst wirkt die Zeitachse gestaucht.
const chartDays = Math.min(Math.max(Number(cfg.chart_days) || 14, 3), 60);
const today = $now.setZone('Europe/Berlin').startOf('day');
const byDay = Object.fromEntries(dailyRaw.map(d => [String(d.day).slice(0, 10), d]));
const known = Object.keys(byDay).sort();
let start = today.minus({ days: chartDays - 1 });
if (known.length) {
  const first = DateTime.fromISO(known[0], { zone: 'Europe/Berlin' });
  if (first > start) start = first;
}
const daily = [];
for (let d = start; d <= today; d = d.plus({ days: 1 })) {
  const key = d.toISODate();
  const v = byDay[key] || {};
  daily.push({
    day: key,
    runs: Number(v.runs) || 0,
    ok_count: Number(v.ok_count) || 0,
    fallback_count: Number(v.fallback_count) || 0,
    error_count: Number(v.error_count) || 0,
    open_count: Number(v.open_count) || 0,
    // Warum null statt 0: unbekannte Kosten sind keine Nullkosten.
    cost_usd: v.cost_usd == null ? null : Number(v.cost_usd),
    cost_unknown_count: Number(v.cost_unknown_count) || 0,
  });
}

const data = {
  generated_at: new Date().toISOString(),
  config: {
    dispatch_enabled: cfg.dispatch_enabled === true,
    branding_allowlist: String(cfg.branding_allowlist || '').split(',').map(s => s.trim()).filter(Boolean),
  },
  runs,
  daily,
  customers,
};

// Warum maskieren: ein "<" im JSON könnte ein </script> in einem Thema schließen (Testlauf 673 enthält genau so einen Text).
const BS = String.fromCharCode(92);
const json = JSON.stringify(data).split('<').join(BS + 'u003c').split(String.fromCharCode(0x2028)).join(BS + 'u2028').split(String.fromCharCode(0x2029)).join(BS + 'u2029');
const html = TEMPLATE.replace('/*__DATA__*/null', () => json);
return [{ json: { html, run_count: runs.length, day_count: daily.length, customer_count: customers.length, template_chars: TEMPLATE.length } }];

// Zweck: prüft ein eingereichtes Branding-Paket und baut das neue branding_pack. Gespeichert wird erst danach und nur bei grüner Prüfung.
const cfg = $('Konfiguration [Edit Fields]').first().json;
// Warum Typprüfung zuerst: unerwartete JSON-Typen (Objekt statt Text) sollen eine 400 ergeben, keinen Absturz.
const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const b = isObj(cfg.body) ? cfg.body : {};
const s = v => (typeof v === 'string' ? v.trim() : '');
const errors = [];
const typeErr = (feld, erwartet) => errors.push(`Feld ${feld} hat den falschen Typ (erwartet ${erwartet}).`);
if (!isObj(cfg.body)) typeErr('body', 'Objekt');
if (b.customer_code !== undefined && typeof b.customer_code !== 'string') typeErr('customer_code', 'Text');
if (b.markenname !== undefined && typeof b.markenname !== 'string') typeErr('markenname', 'Text');
if (b.farben !== undefined && !isObj(b.farben)) typeErr('farben', 'Objekt');
if (b.schriften !== undefined && !isObj(b.schriften)) typeErr('schriften', 'Objekt');
if (b.logo_data_url !== undefined && b.logo_data_url !== null && typeof b.logo_data_url !== 'string') typeErr('logo_data_url', 'Text oder null');
// Warum Pflicht: ohne den Stand der Seite ließe sich eine zwischenzeitliche Änderung still überschreiben.
if (!(Number.isInteger(b.expected_version) && b.expected_version >= 0)) errors.push('Feld expected_version fehlt oder ist keine ganze Zahl ab 0. Bitte Seite neu laden.');

const code = s(b.customer_code).toLowerCase();
// Warum filtern: bei unbekanntem Kunden liefert der Ladeknoten nur ein leeres Element (alwaysOutputData).
const rows = $input.all().map(i => i.json).filter(r => r && r.kuerzel);
const kunde = rows.find(r => r.kuerzel === code) || null;
const allow = String(cfg.branding_allowlist || '').split(',').map(x => x.trim()).filter(Boolean);

if (b.confirmed !== true) errors.push('Die Bestätigung fehlt, nichts wurde gespeichert.');
if (!/^[a-z0-9-]{2,40}$/.test(code) || !kunde) errors.push(`Kunde ${code || '(leer)'} ist unbekannt.`);
// Warum eine Freigabeliste: echte Kunden werden erst nach Patricks Entscheidung über das Dashboard geändert.
if (!(allow.includes('*') || allow.includes(code))) errors.push(`Speichern für ${code || '(leer)'} ist nicht freigegeben (branding_allowlist).`);

const markenname = s(b.markenname);
if (markenname.length < 2 || markenname.length > 80) errors.push('Der Markenname braucht 2 bis 80 Zeichen.');
const keys = ['primaer', 'sekundaer', 'akzent', 'hintergrund', 'text'];
const farbenIn = isObj(b.farben) ? b.farben : {};
const farben = {};
const badColors = [];
for (const k of keys) {
  const v = s(farbenIn[k]).toUpperCase();
  if (/^#[0-9A-F]{6}$/.test(v)) farben[k] = v; else badColors.push(k);
}
if (badColors.length) errors.push(`Kein gültiger Hex-Wert bei: ${badColors.join(', ')}.`);
// Warum nur diese Zeichen: der Name landet später in einer Google-Fonts-Adresse und in CSS.
const fontOk = v => /^[A-Za-z0-9 -]{2,60}$/.test(v);
const schriftenIn = isObj(b.schriften) ? b.schriften : {};
const titel = s(schriftenIn.titel);
const textFont = s(schriftenIn.text);
if (!fontOk(titel)) errors.push('Schrift für Titel fehlt oder enthält unerlaubte Zeichen.');
if (!fontOk(textFont)) errors.push('Schrift für Text fehlt oder enthält unerlaubte Zeichen.');

// Warum Bildstruktur statt 4 Byte Signatur: eine abgeschnittene Datei mit gültigem Kopf darf nicht als Logo durchgehen.
// Hier wird der Aufbau samt Maßen geprüft, bei PNG zusätzlich der entpackte Bildinhalt; dekodiert und neu kodiert wird danach im Knoten Logo neu kodieren [Edit Image].
const MAX_PX = 4096;
// Warum zlib: damit wird der Bildinhalt eines PNG tatsächlich entpackt und Zeile für Zeile gegen die Maße geprüft.
let zlib = null;
try { zlib = require('zlib'); } catch (e) { zlib = null; /* nicht freigegeben: dann prüft allein die Neukodierung im Knoten Logo neu kodieren */ }
const crcTable = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = (buf, start, end) => { let c = 0xFFFFFFFF; for (let i = start; i < end; i++) c = crcTable[(c ^ buf[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
function checkPng(buf) {
  if (buf.length < 8 + 25 + 12 + 12) return 'PNG ist zu kurz.';
  if (buf.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a') return 'PNG-Kennung fehlt.';
  let pos = 8, w = 0, h = 0, idat = 0, iend = false, first = true, depth = 0, ctype = 0, interlace = 0;
  const parts = [];
  while (pos + 12 <= buf.length) {
    const len = buf.readUInt32BE(pos);
    const type = buf.subarray(pos + 4, pos + 8).toString('latin1');
    if (!/^[A-Za-z]{4}$/.test(type)) return 'PNG-Block mit ungültigem Namen.';
    if (pos + 12 + len > buf.length) return `PNG-Block ${type} ist abgeschnitten.`;
    if (crc32(buf, pos + 4, pos + 8 + len) !== buf.readUInt32BE(pos + 8 + len)) return `PNG-Block ${type} hat eine falsche Prüfsumme.`;
    if (first) {
      if (type !== 'IHDR' || len !== 13) return 'PNG beginnt nicht mit IHDR.';
      w = buf.readUInt32BE(pos + 8); h = buf.readUInt32BE(pos + 12);
      depth = buf[pos + 16]; ctype = buf[pos + 17]; interlace = buf[pos + 20];
      if (![1, 2, 4, 8, 16].includes(depth) || ![0, 2, 3, 4, 6].includes(ctype)) return 'PNG mit ungültiger Farbtiefe.';
      first = false;
    }
    if (type === 'IDAT') { idat++; parts.push(buf.subarray(pos + 8, pos + 8 + len)); }
    pos += 12 + len;
    if (type === 'IEND') { iend = true; break; }
  }
  if (!idat) return 'PNG ohne Bilddaten.';
  if (!iend || pos !== buf.length) return 'PNG ist unvollständig oder hat Anhängsel nach dem Ende.';
  if (w < 1 || h < 1 || w > MAX_PX || h > MAX_PX) return `PNG misst ${w} x ${h} Pixel, erlaubt sind 1 bis ${MAX_PX}.`;
  if (zlib) {
    const ch = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ctype];
    const bits = depth * ch;
    const passes = interlace === 1 ? [[0, 0, 8, 8], [4, 0, 8, 8], [0, 4, 4, 8], [2, 0, 4, 4], [0, 2, 2, 4], [1, 0, 2, 2], [0, 1, 1, 2]] : [[0, 0, 1, 1]];
    const rows = [];
    for (const [xs, ys, dx, dy] of passes) {
      const pw = Math.ceil((w - xs) / dx), ph = Math.ceil((h - ys) / dy);
      if (pw > 0 && ph > 0) for (let r = 0; r < ph; r++) rows.push(1 + Math.ceil((pw * bits) / 8));
    }
    const expected = rows.reduce((a, n) => a + n, 0);
    let raw;
    try { raw = zlib.inflateSync(Buffer.concat(parts), { maxOutputLength: expected + 1 }); } catch (e) { return 'PNG-Bilddaten lassen sich nicht entpacken (' + String(e.code || e.message).slice(0, 40) + ').'; }
    if (raw.length !== expected) return `PNG-Bilddaten haben ${raw.length} statt ${expected} Byte.`;
    let off = 0;
    for (const n of rows) { if (raw[off] > 4) return 'PNG-Bildzeile mit ungültigem Filter.'; off += n; }
  }
  return { w, h };
}
function checkJpeg(buf) {
  if (buf.length < 4 || buf[0] !== 0xFF || buf[1] !== 0xD8) return 'JPG-Kennung fehlt.';
  if (buf[buf.length - 2] !== 0xFF || buf[buf.length - 1] !== 0xD9) return 'JPG ist unvollständig (Endmarke fehlt).';
  let pos = 2, w = 0, h = 0;
  while (pos + 4 <= buf.length) {
    if (buf[pos] !== 0xFF) return 'JPG-Aufbau ist beschädigt.';
    const m = buf[pos + 1];
    if (m === 0xFF) { pos++; continue; }
    if (m === 0xD8 || (m >= 0xD0 && m <= 0xD7) || m === 0x01) { pos += 2; continue; }
    const len = buf.readUInt16BE(pos + 2);
    if (len < 2 || pos + 2 + len > buf.length) return 'JPG-Segment ist abgeschnitten.';
    if (m >= 0xC0 && m <= 0xCF && ![0xC4, 0xC8, 0xCC].includes(m)) { if (len < 7) return 'JPG-Bildkopf ist zu kurz.'; h = buf.readUInt16BE(pos + 5); w = buf.readUInt16BE(pos + 7); }
    if (m === 0xDA) break;
    pos += 2 + len;
  }
  if (!w || !h) return 'JPG ohne Bildmaße.';
  return { w, h };
}
function checkWebp(buf) {
  if (buf.length < 30) return 'WEBP ist zu kurz.';
  if (buf.subarray(0, 4).toString('latin1') !== 'RIFF' || buf.subarray(8, 12).toString('latin1') !== 'WEBP') return 'WEBP-Kennung fehlt.';
  if (buf.readUInt32LE(4) + 8 !== buf.length) return 'WEBP ist unvollständig (Längenangabe passt nicht).';
  const chunk = buf.subarray(12, 16).toString('latin1');
  if (chunk === 'VP8 ') {
    if (buf.subarray(23, 26).toString('hex') !== '9d012a') return 'WEBP-Bildkopf ist beschädigt.';
    return { w: buf.readUInt16LE(26) & 0x3FFF, h: buf.readUInt16LE(28) & 0x3FFF };
  }
  if (chunk === 'VP8L') {
    if (buf[20] !== 0x2F) return 'WEBP-Bildkopf ist beschädigt.';
    const bits = buf.readUInt32LE(21);
    return { w: (bits & 0x3FFF) + 1, h: ((bits >>> 14) & 0x3FFF) + 1 };
  }
  if (chunk === 'VP8X') return { w: buf.readUIntLE(24, 3) + 1, h: buf.readUIntLE(27, 3) + 1 };
  return 'WEBP mit unbekanntem Bildformat.';
}

let logo = null;
if (typeof b.logo_data_url === 'string' && b.logo_data_url) {
  const m = /^data:(image\/(png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/.exec(b.logo_data_url);
  if (!m) {
    errors.push('Das Logo ist kein PNG, JPG oder WEBP.');
  } else {
    const buf = Buffer.from(m[3], 'base64');
    if (buf.length > 1000000) errors.push(`Das Logo ist ${(buf.length / 1e6).toFixed(1)} MB groß, erlaubt ist 1 MB.`);
    else {
      const res = m[2] === 'png' ? checkPng(buf) : m[2] === 'jpeg' ? checkJpeg(buf) : checkWebp(buf);
      if (typeof res === 'string') errors.push(`Das Logo ist keine gültige Bilddatei: ${res}`);
      else if (res.w < 1 || res.h < 1 || res.w > MAX_PX || res.h > MAX_PX) errors.push(`Das Logo misst ${res.w} x ${res.h} Pixel, erlaubt sind 1 bis ${MAX_PX}.`);
      else {
        const ext = m[2] === 'jpeg' ? 'jpg' : m[2];
        logo = { b64: m[3], mime: m[1], ext, size: buf.length, width: res.w, height: res.h };
      }
    }
  }
}

// Warum Versionsvergleich: zwei gleichzeitige Einreichungen dürfen sich nicht still überschreiben.
const alt = isObj(kunde?.branding_pack) ? kunde.branding_pack : {};
const dbVersion = /^[0-9]{1,9}$/.test(String(alt.version ?? '')) ? Number(alt.version) : 0;
const expected = Number.isInteger(b.expected_version) ? b.expected_version : dbVersion;
let status_code = 400;
if (errors.length === 0 && expected !== dbVersion) {
  status_code = 409;
  errors.push(`Das Branding wurde inzwischen geändert (gespeichert ist Version ${dbVersion}, die Seite kannte Version ${expected}). Bitte Seite neu laden und erneut einreichen.`);
}

const ok = errors.length === 0;
const newVersion = dbVersion + 1;
const stamp = $now.setZone('Europe/Berlin');
// Warum eigener Pfad je Version: das bisherige Logo wird nie überschrieben; erst das erfolgreiche Speichern stellt auf den neuen Pfad um.
// Warum immer .png: das Logo wird im Knoten Logo neu kodieren dekodiert und als PNG neu geschrieben.
const logoPath = ok && logo ? `logos/${code}/v${newVersion}-${$execution.id}.png` : null;
const branding_pack = ok ? {
  ...alt,
  markenname,
  farben,
  schriften: { ...(isObj(alt.schriften) ? alt.schriften : {}), titel, text: textFont },
  logo: logo ? { ...(isObj(alt.logo) ? alt.logo : {}), modus: 'datei', pfad: logoPath, text: markenname } : (alt.logo || null),
  status: 'eingereicht',
  eingereicht_am: stamp.toISO(),
  quelle: `K1 Dashboard, eingereicht ${stamp.toFormat('dd.MM.yyyy HH:mm')}`,
  version: newVersion,
} : null;

const out = {
  ok,
  customer_code: code,
  has_logo: ok && !!logo,
  logo_path: logoPath,
  logo_size: logo?.size || null,
  logo_dimensions: logo ? `${logo.width}x${logo.height}` : null,
  logo_decode: logo ? (logo.mime === 'image/png' && zlib ? 'png-entpackt-und-neu-kodiert' : 'neu-kodiert') : null,
  expected_version: ok ? dbVersion : null,
  branding_pack,
  status_code: ok ? 200 : status_code,
  response: ok ? null : { ok: false, message: 'Branding nicht gespeichert.', errors },
};
const item = { json: out };
if (ok && logo) item.binary = { logo: { data: logo.b64, mimeType: logo.mime, fileName: `v${newVersion}-eingang.${logo.ext}` } };
return [item];

// Zweck: wertet die Antwort der Funktion k1_dashboard_save_branding aus und baut die Antwort an die Seite.
const pruef = $('Branding prüfen [Code]').first().json;
const r = $input.first()?.json || {};
const logoHinweis = pruef.has_logo ? ' Das neu hochgeladene Logo wurde nicht übernommen, das bisherige gilt weiter.' : '';
// Warum Status statt Zeilenzählung: die Funktion speichert nur, wenn die erwartete Version noch gilt.
if (r.ok === true && r.status === 'saved') {
  const bp = (r.branding_pack && typeof r.branding_pack === 'object') ? r.branding_pack : {};
  const logoText = pruef.has_logo ? ` Logo gespeichert unter ${r.logo_url}.` : ' Logo unverändert.';
  return [{ json: {
    status_code: 200,
    response: {
      ok: true,
      message: `Branding für ${pruef.customer_code} gespeichert (Version ${bp.version}).${logoText}`,
      version: bp.version,
      // Warum mitsenden: die Seite übernimmt den gespeicherten Stand, statt beim nächsten Wechsel den alten zu zeigen.
      branding: { markenname: bp.markenname ?? null, farben: bp.farben ?? null, schriften: bp.schriften ?? null, version: Number(bp.version) || 0 },
    },
  } }];
}
if (r.status === 'conflict') {
  return [{ json: { status_code: 409, response: { ok: false, message: `Nicht gespeichert: Das Branding wurde gleichzeitig geändert (jetzt Version ${r.current_version}, erwartet ${r.expected_version}). Bitte Seite neu laden und erneut einreichen.${logoHinweis}` } } }];
}
if (r.status === 'not_found') {
  return [{ json: { status_code: 404, response: { ok: false, message: `Nicht gespeichert: Kunde ${pruef.customer_code} gibt es nicht mehr.${logoHinweis}` } } }];
}
return [{ json: { status_code: 502, response: { ok: false, message: `Nicht gespeichert: unerwartete Antwort der Datenbank (${String(r.status || r.message || 'leer').slice(0, 80)}).${logoHinweis}` } } }];

// Zweck: liest nach einem Fehler beim oder nach dem Speichern den tatsächlichen Stand und meldet ihn ehrlich.
const pruef = $('Branding prüfen [Code]').first().json;
const want = pruef.branding_pack || {};
const row = $input.all().map(i => i.json).find(r => r && r.kuerzel === pruef.customer_code) || null;
const bp = row && row.branding_pack && typeof row.branding_pack === 'object' ? row.branding_pack : null;
const version = bp ? Number(bp.version) || 0 : null;
// Warum Zeitstempel und Version: nur das eigene Paket trägt genau diese Einreichungszeit.
const saved = !!bp && bp.eingereicht_am === want.eingereicht_am && version === Number(want.version) && (!pruef.has_logo || row.logo_url === pruef.logo_path);
if (saved) {
  return [{ json: { status_code: 200, response: { ok: true, message: `Branding für ${pruef.customer_code} gespeichert (Version ${version}, nach einer Störung durch Nachlesen bestätigt).`, version, branding: { markenname: bp.markenname ?? null, farben: bp.farben ?? null, schriften: bp.schriften ?? null, version } } } }];
}
if (bp && version === Number(pruef.expected_version)) {
  return [{ json: { status_code: 502, response: { ok: false, message: `Nicht gespeichert: Nachlesen zeigt weiterhin Version ${version}. Bisheriges Branding und Logo gelten weiter. Bitte später erneut versuchen.` } } }];
}
return [{ json: { status_code: 409, response: { ok: false, message: `Speicherstand unklar: Nachlesen zeigt ${bp ? 'Version ' + version : 'keinen Kunden'}. Bitte Seite neu laden und den Stand prüfen, bevor Sie erneut einreichen.` } } }];
